def text_of(f):
    return re.sub(r'\s+', ' ', ' '.join(str(f.get(k) or '') for k in ['text','pros','cons'])).strip()

def short_quote(f):
    text = text_of(f)
    words = text.split()
    return {'text':' '.join(words[:10])+('…' if len(words)>10 else ''),
            'date':f.get('createdDate','')[:10], 'stars':f.get('productValuation'), 'nm':f.get('nmId')}

def assemble(nm,note):
    d=json.loads(Path(f'data/products/{nm}.json').read_text(encoding='utf8'))
    c,f=d['card'],d['feedback']
    name,use,budget,pros,cons,summary=note
    reviews=[r for r in f.get('feedbacks') or [] if r.get('nmId')==nm and len(text_of(r).split())>=2]
    clean=[r for r in reviews if not re.search(r'хрена|карли|туфта|шлаком|охрен|деньги|валберис|день рождения|другие штаны',text_of(r),re.I)]
    positive=next((r for r in clean if (r.get('productValuation') or 0)>=4),None)
    negative=next((r for r in sorted(clean,key=lambda r:r.get('productValuation') or 5) if (r.get('productValuation') or 5)<=3 and r is not positive),None)
    quotes=[short_quote(r) for r in [positive,negative] if r]
    if not quotes and reviews:
        quotes=[short_quote(reviews[0])]
    specs={o['name']:o['value'] for o in c.get('options',[]) if o['name'] in [
        'Сезон','Состав','Пол','Материал подкладки','Утеплитель','Вид застежки','Плотность синтетического утеплителя',
        'Материал изделия','Комплектация','Температурный режим','Опции капюшона'] and len(str(o['value']))<180}
    if not specs:
        specs={'Описание продавца':re.sub(r'\s+',' ',c.get('description',''))[:240]}
    cat=next(cat for cat,ids in RANKS.items() if nm in ids) if any(nm in ids for ids in RANKS.values()) else d['category']
    # Search can mislabel a result; category is explicitly curated here.
    if nm in [105015382,173541014,577489565]:cat='jackets'
    if nm in [175105947,173886295,282932998,132758383]:cat='pants'
    rank=RANKS[cat].index(nm)+1 if nm in RANKS[cat] else None
    return dict(id=nm,category=cat,name=name,brand=(c.get('selling') or {}).get('brand_name') or 'Без бренда',
        use=use,budget=budget,pros=pros,cons=cons,reviewSummary=summary,rank=rank,reason=REASONS.get(nm),
        rating=f.get('valuation'),count=f.get('feedbackCount') or 0,quotes=quotes,specs=specs,
        cardSource=c['_source'],reviewSource=f"https://feedbacks2.wb.ru/feedbacks/v1/{c['imt_id']}",
        imt=c['imt_id'],exactTextReviews=len(reviews),imageSource=f"https://basket-{c['_basket_host']}.wbbasket.ru/vol{nm//100000}/part{nm//1000}/{nm}/images/big/1.webp")

def get_image(p):
    out=Path(f"assets/products/{p['id']}.webp")
    out.parent.mkdir(parents=True,exist_ok=True)
    if out.exists():return
    c=StaticClient()
    for attempt in range(3):
        try:
            r=c.session.get(p['imageSource'],timeout=20)
            r.raise_for_status()
            if not r.headers.get('Content-Type','').startswith('image/'):
                raise RuntimeError('Response is not an image')
            out.write_bytes(r.content)
            return
        except Exception:
            if attempt==2:raise

